/**
 * Frontmatter parsers. Authored markdown (skill descriptions, schedule cron
 * expressions) uses the flat `key: value` scalar subset; Cursor plugin
 * markdown is full YAML (folded descriptions, lists).
 */
import { JSON_SCHEMA, load as parseYaml } from "js-yaml";
import { isRecord } from "./is-record.js";
const FRONTMATTER_OPEN = /^---\s*$/;
const YAML_FRONTMATTER = /^---\r?\n([\s\S]*?)\r?\n---(?:\r?\n|$)([\s\S]*)$/;
/** YAML frontmatter with the JSON schema (no custom tags). */
export function parseYamlFrontmatter(source) {
    const match = YAML_FRONTMATTER.exec(source);
    if (match === null) {
        return { data: {}, body: source };
    }
    const body = match[2] ?? "";
    let data;
    try {
        data = parseYaml(match[1] ?? "", { schema: JSON_SCHEMA });
    }
    catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        return { data: {}, body, error: message };
    }
    if (data === undefined || data === null) {
        return { data: {}, body };
    }
    if (typeof data !== "object" || Array.isArray(data)) {
        return { data: {}, body, error: "frontmatter is not a mapping" };
    }
    if (!isRecord(data)) {
        return { data: {}, body, error: "frontmatter is not a mapping" };
    }
    return { data, body };
}
export function parseFrontmatter(source) {
    const lines = source.split(/\r?\n/);
    if (lines.length === 0 || !FRONTMATTER_OPEN.test(lines[0] ?? "")) {
        return { data: {}, body: source };
    }
    let closeIndex = -1;
    for (let i = 1; i < lines.length; i++) {
        if (FRONTMATTER_OPEN.test(lines[i] ?? "")) {
            closeIndex = i;
            break;
        }
    }
    if (closeIndex === -1) {
        return { data: {}, body: source };
    }
    const data = {};
    for (const line of lines.slice(1, closeIndex)) {
        if (line.trim() === "" || line.trim().startsWith("#")) {
            continue;
        }
        const separator = line.indexOf(":");
        if (separator === -1) {
            continue;
        }
        const key = line.slice(0, separator).trim();
        if (key === "") {
            continue;
        }
        data[key] = unquote(line.slice(separator + 1).trim());
    }
    const body = lines
        .slice(closeIndex + 1)
        .join("\n")
        .replace(/^\n+/, "");
    return { data, body };
}
export function serializeFrontmatter(data) {
    const lines = Object.entries(data).map(([key, value]) => `${key}: ${quoteIfNeeded(value)}`);
    return `---\n${lines.join("\n")}\n---\n`;
}
function unquote(value) {
    if (value.length >= 2 &&
        ((value.startsWith('"') && value.endsWith('"')) ||
            (value.startsWith("'") && value.endsWith("'")))) {
        return value.slice(1, -1);
    }
    return value;
}
function quoteIfNeeded(value) {
    if (/[:#'"\n]/.test(value)) {
        return JSON.stringify(value);
    }
    return value;
}
